using MiniStore.Domain.Entities; using MiniStore.Domain.Interfaces.Accounting;
namespace MiniStore.Application.Services.Accounting;
public sealed class BankReconciliationService(IBankReconciliationRepository repository)
{ public async Task<decimal> GetStatementRemainingAsync(int lineId){var line=await repository.GetStatementLineAsync(lineId)??throw new ArgumentException("Statement line was not found.");var allocated=await repository.GetActiveStatementAllocationAsync(lineId);return Math.Max(0m,(line.Debit+line.Credit)-allocated);} public async Task EnsureStatementCapacityAsync(int lineId,decimal amount){if(amount<=0)throw new ArgumentException("Match amount must be positive.");if(amount>await GetStatementRemainingAsync(lineId))throw new InvalidOperationException("Match amount exceeds the remaining statement-line amount.");} public async Task EnsureJournalCompatibilityAsync(int statementLineId,int journalLineId,decimal amount){var statement=await repository.GetStatementLineAsync(statementLineId)??throw new ArgumentException("Statement line was not found.");var journal=await repository.GetJournalLineAsync(journalLineId)??throw new ArgumentException("Journal line was not found.");var bankAccountId=await repository.GetStatementAccountIdAsync(statementLineId);if(!bankAccountId.HasValue||journal.Line.AccountId!=bankAccountId.Value)throw new InvalidOperationException("The journal line must use the linked bank ledger account.");if(journal.Status!=JournalEntryStatus.Posted)throw new InvalidOperationException("Only posted journal lines can be matched.");if((statement.Debit>0)!=(journal.Line.Debit>0))throw new InvalidOperationException("Statement and journal directions must match.");var remaining=Math.Max(0m,(journal.Line.Debit+journal.Line.Credit)-(await repository.GetActiveJournalAllocationAsync(journalLineId)));if(amount>remaining)throw new InvalidOperationException("Match amount exceeds the remaining journal-line amount.");} }
